DELIMITER $$
CREATE TRIGGER `trg_min_3_criterios` AFTER DELETE ON `criterio_aceptacion` FOR EACH ROW BEGIN
          DECLARE n INT;
          SELECT COUNT(*) INTO n FROM Criterio_Aceptacion WHERE id_funcionalidad = OLD.id_funcionalidad;
          IF n < 3 THEN
